<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{DB,Mail,Queue,Http};
use App\Models\User;
class MarketingEmailBatchTest extends TestCase {
 use RefreshDatabase;
 private function fixture():array {Queue::fake();Mail::fake();Http::preventStrayRequests();$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]);$this->actingAs($u);config(['mail.default'=>'smtp','mail.from.address'=>'sender@example.test','marketing.email_bulk_enabled'=>false]);config(['marketing.email_smtp_hosts'=>['smtp.example.test']]);$settings=app(\App\Services\Marketing\MarketingEmailSettings::class);$settings->save(['version'=>0,'host'=>'smtp.example.test','port'=>587,'encryption'=>'tls','username'=>'sender@example.test','password'=>'fake-only','from_name'=>'Test store','from_address'=>'sender@example.test','reply_to'=>'','minute_limit'=>1000,'hour_limit'=>1000,'day_limit'=>1000,'unit_minor'=>2,'currency'=>'USD']);$raw=$settings->raw();$raw['verified_at']=now()->toIso8601String();\App\Models\StoreSetting::where('key',$settings->key())->update(['value'=>json_encode($raw)]);$dir=app(\App\Services\Marketing\Audience\AudienceDirectory::class);foreach(['yes','no','stop'] as $n){$dir->project('newsletter',$n,['name'=>'Sample '.$n,'email'=>$n.'@example.test'],'batch-test');if($n!=='no')$dir->subscribe('email',$n.'@example.test',$n==='stop'?'unsubscribed':'subscribed','test',now());}
 $id=(string)\Illuminate\Support\Str::uuid();DB::table('marketing_audience_segments')->insert(['id'=>$id,'merchant_key'=>$dir->merchant(),'user_id'=>$u->id,'name'=>'All test contacts','description'=>'','rules'=>json_encode(['match'=>'all','conditions'=>[['field'=>'source','operator'=>'eq','value'=>'newsletter']]]),'status'=>'active','version'=>1,'created_at'=>now(),'updated_at'=>now()]);
 $t=app(\App\Services\Marketing\MarketingContentTemplates::class)->save($u->id,['version'=>0,'channel'=>'email','name'=>'Batch test','language'=>'en','body'=>'Hello {{first_name}}, explore our shop.','subject'=>'Hello {{first_name}}','format'=>'image']);return app(\App\Services\Marketing\MarketingCampaigns::class)->saveChannelDraft($u->id,['version'=>0,'channel'=>'email','name'=>'Segment test','document'=>['template_id'=>$t['id'],'segment_id'=>$id]],null);}
 public function test_review_excludes_without_sending_and_confirmation_is_closed_by_default():void {$c=$this->fixture();$r=$this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-batches/review',['version'=>$c['version'],'landing_url'=>url('/')])->assertCreated()->assertJsonPath('batch.total',1)->assertJsonPath('batch.excluded',2);$this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-batches/'.$r->json('batch.id').'/confirm',['confirmed'=>true,'version'=>$c['version'],'cost_limit_minor'=>0])->assertStatus(409);Queue::assertNothingPushed();Mail::assertNothingSent();Http::assertNothingSent();}
 private function reviewed(array $price=[]):array {$c=$this->fixture();config(array_merge(['marketing.email_bulk_enabled'=>true,'marketing.email_bulk_unit_minor'=>2,'marketing.email_bulk_currency'=>'USD'],$price));$settings=app(\App\Services\Marketing\MarketingEmailSettings::class);$raw=$settings->raw();$raw['unit_minor']=config('marketing.email_bulk_unit_minor');\App\Models\StoreSetting::where('key',$settings->key())->update(['value'=>json_encode($raw)]);$b=$this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-batches/review',['version'=>$c['version'],'landing_url'=>url('/')])->assertCreated()->json('batch');return [$c,$b];}
 private function confirmBatch(array $c,array $b){return $this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-batches/'.$b['id'].'/confirm',['confirmed'=>true,'version'=>$c['version'],'cost_limit_minor'=>$b['cost_limit_minor']]);}
 public function test_repeat_review_confirmation_and_worker_do_not_duplicate():void {[$c,$b]=$this->reviewed();$again=$this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-batches/review',['version'=>$c['version'],'landing_url'=>url('/')])->assertCreated()->json('batch');$this->assertSame($b['id'],$again['id']);$this->confirmBatch($c,$b)->assertOk();$this->confirmBatch($c,$b)->assertOk();$s=app(\App\Services\Marketing\MarketingEmailBatches::class);$s->run($b['id']);$s->run($b['id']);$this->assertDatabaseHas('marketing_email_batches',['id'=>$b['id'],'state'=>'completed','cursor'=>1]);$this->assertDatabaseCount('marketing_email_deliveries',1);Mail::assertSent(\App\Mail\MarketingCampaignTestMail::class,1);$delivery=DB::table('marketing_email_deliveries')->first();$doc=json_decode($delivery->snapshot,true);$this->assertSame('Hello Sample',$doc['subject']);$this->assertStringNotContainsString('[TEST]',$doc['subject']);$this->assertStringContainsString('/m/r/',$doc['html']);$this->assertArrayHasKey('unsubscribe_url',$doc);Http::assertNothingSent();}
 public function test_later_unsubscribe_blocks_frozen_recipient():void {[$c,$b]=$this->reviewed();$this->confirmBatch($c,$b)->assertOk();app(\App\Services\Marketing\Audience\AudienceDirectory::class)->subscribe('email','yes@example.test','unsubscribed','test',now());app(\App\Services\Marketing\MarketingEmailBatches::class)->run($b['id']);$this->assertDatabaseHas('marketing_email_deliveries',['state'=>'blocked']);Mail::assertNothingSent();}
 public function test_unknown_result_pauses_without_resubmitting():void {[$c,$b]=$this->reviewed();$this->confirmBatch($c,$b)->assertOk();Mail::shouldReceive('purge')->andReturnNull();Mail::shouldReceive('mailer')->with('marketing_campaign')->andReturnSelf();Mail::shouldReceive('to')->once()->andThrow(new \RuntimeException('unconfirmed'));$s=app(\App\Services\Marketing\MarketingEmailBatches::class);$s->run($b['id']);$s->run($b['id']);$this->assertDatabaseHas('marketing_email_batches',['id'=>$b['id'],'state'=>'paused','error_code'=>'submission_unconfirmed']);$this->assertDatabaseHas('marketing_email_deliveries',['state'=>'unknown']);}
 public function test_unknown_cost_changed_inputs_and_foreign_owner_cannot_confirm():void {[$c,$b]=$this->reviewed(['marketing.email_bulk_unit_minor'=>null]);$this->confirmBatch($c,array_replace($b,['cost_limit_minor'=>0]))->assertStatus(409);config(['marketing.email_bulk_unit_minor'=>2]);$this->actingAs(User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]));$this->confirmBatch($c,array_replace($b,['cost_limit_minor'=>0]))->assertNotFound();Mail::assertNothingSent();Queue::assertNothingPushed();}
 public function test_feedback_is_repeat_safe_suppresses_hard_bounce_and_preserves_terminal_result():void {[$c,$b]=$this->reviewed();$this->confirmBatch($c,$b)->assertOk();app(\App\Services\Marketing\MarketingEmailBatches::class)->run($b['id']);$r=DB::table('marketing_email_deliveries')->first();$f=app(\App\Services\Marketing\MarketingEmailFeedback::class);$f->recordVerified($r->merchant_key,$r->id,'fake','event-1','hard_bounce');$f->recordVerified($r->merchant_key,$r->id,'fake','event-1','hard_bounce');$f->recordVerified($r->merchant_key,$r->id,'fake','event-2','delivered');$this->assertDatabaseCount('marketing_email_feedback',2);$this->assertDatabaseHas('marketing_email_deliveries',['id'=>$r->id,'state'=>'bounced','error_code'=>'hard_bounce']);$this->assertDatabaseHas('marketing_audience_subscriptions',['destination_hash'=>hash('sha256','yes@example.test'),'status'=>'suppressed']);}
 public function test_changed_price_and_permission_block_before_sending():void {[$c,$b]=$this->reviewed();$this->confirmBatch($c,$b)->assertOk();config(['marketing.email_bulk_unit_minor'=>3]);$settings=app(\App\Services\Marketing\MarketingEmailSettings::class);$raw=$settings->raw();$raw['unit_minor']=3;\App\Models\StoreSetting::where('key',$settings->key())->update(['value'=>json_encode($raw)]);app(\App\Services\Marketing\MarketingEmailBatches::class)->run($b['id']);$this->assertDatabaseHas('marketing_email_batches',['id'=>$b['id'],'state'=>'paused','error_code'=>'sender_or_cost_changed']);Mail::assertNothingSent();$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>false]);$u->permissions()->create(['permission'=>'marketing.view']);$this->actingAs($u);$this->getJson('/admin/marketing/campaigns/'.$c['id'].'/email-batches')->assertForbidden();}
 public function test_review_keeps_frozen_membership():void {[$c,$b]=$this->reviewed();$dir=app(\App\Services\Marketing\Audience\AudienceDirectory::class);for($i=0;$i<26;$i++){$email='chunk'.$i.'@example.test';$dir->project('newsletter','chunk'.$i,['email'=>$email,'name'=>'Chunk'],'test');$dir->subscribe('email',$email,'subscribed','test',now());} $this->confirmBatch($c,$b)->assertOk();app(\App\Services\Marketing\MarketingEmailBatches::class)->run($b['id']);$this->assertDatabaseHas('marketing_email_batches',['id'=>$b['id'],'total'=>1,'cursor'=>1]);Mail::assertSent(\App\Mail\MarketingCampaignTestMail::class,1);}
 public function test_changed_campaign_or_segment_and_unconfirmed_request_are_rejected():void {[$c,$b]=$this->reviewed();$path='/admin/marketing/campaigns/'.$c['id'].'/email-batches/'.$b['id'].'/confirm';$this->postJson($path,['confirmed'=>false,'version'=>$c['version'],'cost_limit_minor'=>2])->assertUnprocessable();DB::table('marketing_audience_segments')->where('id',$c['document']['segment_id'])->increment('version');$this->confirmBatch($c,$b)->assertStatus(409);Queue::assertNothingPushed();Mail::assertNothingSent();}
 public function test_chunks_advance_25_then_finish_without_duplicate_and_lock_campaign_save():void {$c=$this->fixture();$dir=app(\App\Services\Marketing\Audience\AudienceDirectory::class);for($i=0;$i<26;$i++){$email='page'.$i.'@example.test';$dir->project('newsletter','page'.$i,['email'=>$email,'name'=>'Page'],'test');$dir->subscribe('email',$email,'subscribed','test',now());}config(['marketing.email_bulk_enabled'=>true,'marketing.email_bulk_unit_minor'=>1]);$b=$this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-batches/review',['version'=>$c['version'],'landing_url'=>url('/')])->assertCreated()->assertJsonPath('batch.total',27)->json('batch');$this->confirmBatch($c,$b)->assertOk();$this->postJson('/admin/marketing/campaigns/channel-drafts/'.$c['id'],['channel'=>'email','name'=>'Changed','version'=>$c['version'],'document'=>['template_id'=>$c['document']['template_id'],'segment_id'=>$c['document']['segment_id']]])->assertStatus(409);$service=app(\App\Services\Marketing\MarketingEmailBatches::class);$service->run($b['id']);$this->assertDatabaseHas('marketing_email_batches',['id'=>$b['id'],'state'=>'queued','cursor'=>25]);$service->run($b['id']);$service->run($b['id']);$this->assertDatabaseHas('marketing_email_batches',['id'=>$b['id'],'state'=>'completed','cursor'=>27]);Mail::assertSent(\App\Mail\MarketingCampaignTestMail::class,27);}
 public function test_review_expiry_and_cost_approval_permission_are_enforced():void {[$c,$b]=$this->reviewed();DB::table('marketing_email_batches')->where('id',$b['id'])->update(['expires_at'=>now()->subMinute()]);$this->confirmBatch($c,$b)->assertStatus(409);$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>false]);foreach(['marketing.view','marketing.manage_campaigns','marketing.view_audience'] as $p)$u->permissions()->create(['permission'=>$p]);DB::table('marketing_campaigns')->where('id',$c['id'])->update(['user_id'=>$u->id]);DB::table('marketing_email_batches')->where('id',$b['id'])->update(['user_id'=>$u->id]);$this->actingAs($u);$this->confirmBatch($c,$b)->assertForbidden();Mail::assertNothingSent();}

 public function test_page_continuation_requires_confirmation_and_never_resends_completed_batch():void {
  [$c,$b]=$this->reviewed();config(['marketing.execution_enabled'=>false]);$url='/admin/marketing/campaigns/'.$c['id'].'/email-batches/'.$b['id'].'/continue';
  $this->postJson($url)->assertStatus(409);Mail::assertNothingSent();
  $this->confirmBatch($c,$b)->assertOk();$this->postJson($url)->assertOk()->assertJsonPath('batch.state','completed');
  $this->postJson($url)->assertOk()->assertJsonPath('batch.state','completed');Mail::assertSent(\App\Mail\MarketingCampaignTestMail::class,1);
  $other=User::factory()->create(['is_admin'=>true]);$this->actingAs($other)->postJson($url)->assertForbidden();
 }

 public function test_page_ticks_send_one_recipient_and_pause_unknown_without_retry():void {
  $c=$this->fixture();config(['marketing.email_bulk_enabled'=>true]);$dir=app(\App\Services\Marketing\Audience\AudienceDirectory::class);
  foreach(['second','third'] as $name){$dir->project('newsletter',$name,['email'=>$name.'@example.test'],'page-tick');$dir->subscribe('email',$name.'@example.test','subscribed','test',now());}
  $b=$this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-batches/review',['version'=>$c['version'],'landing_url'=>url('/')])->assertCreated()->json('batch');$this->confirmBatch($c,$b)->assertOk();
  $url='/admin/marketing/campaigns/'.$c['id'].'/email-batches/'.$b['id'].'/continue';
  $this->postJson($url)->assertOk()->assertJsonPath('batch.processed',1)->assertJsonPath('batch.state','queued');Mail::assertSent(\App\Mail\MarketingCampaignTestMail::class,1);
  DB::table('marketing_email_batches')->where('id',$b['id'])->update(['state'=>'processing','updated_at'=>now()->subMinutes(3)]);
  $this->postJson($url)->assertOk()->assertJsonPath('batch.state','paused');$this->postJson($url)->assertOk()->assertJsonPath('batch.state','paused');Mail::assertSent(\App\Mail\MarketingCampaignTestMail::class,1);
 }
}
